#include <stdio.h>
 #include <stdlib.h>


 struct Node {
  int data;
  struct Node* next;
 };


 void insAtBegining(struct Node** head_ref, int new_data) {

  struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));


  new_node->data = new_data;

  new_node->next = (*head_ref);


  (*head_ref) = new_node;
 }



 void insAtEnd(struct Node** head_ref, int new_data) {
  struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
  struct Node* last = *head_ref; 

  new_node->data = new_data;
  new_node->next = NULL;

  if (*head_ref == NULL) {
  *head_ref = new_node;
  return;
  }

  while (last->next != NULL) last = last->next;

  last->next = new_node;
  return;
 }


 void printList(struct Node* node) {
  while (node != NULL) {
  printf(" %d ", node->data);
  node = node->next;
  }
 }


 int main() {


  int n;
  scanf("%d",&n);
  while(n--){
  int p,v;
  scanf("%d%d",&p,&v);
  struct Node* head = NULL;

  if(p==0){
  insAtBegining(&head, v);

  }
  else{
  insAtEnd(&head, v);

  }







  printList(head);
 }

  return 0;


 }

