#include <stdio.h>
 #include <stdlib.h>
 #include <ctype.h>

 #define MAX 100

 int stack[MAX];
 int top = -1;

 // Push to stack
 void push(int x) {
  if(top < MAX-1)
  stack[++top] = x;
  else
  printf("Stack overflow\n");
 }

 // Pop from stack
 int pop() {
  if(top >= 0)
  return stack[top--];
  else {
  printf("Stack underflow\n");
  return 0;
  }
 }

 // Evaluate a postfix expression
 int evaluate(char* expr) {
  top = -1; // reset stack
  for(int i=0; expr[i] != '\0'; i++) {
  char ch = expr[i];

  if(isdigit(ch)) {
  push(ch - '0'); // push digit
  }
  else if(ch == '+') {
  int b = pop();
  int a = pop();
  push(a + b);
  }
  else if(ch == '-') {
  int b = pop();
  int a = pop();
  push(a - b);
  }
  else if(ch == '*') {
  int b = pop();
  int a = pop();
  push(a * b);
  }
  else if(ch == '/') {
  int b = pop();
  int a = pop();
  if(b == 0) b += 2; // special rule
  push(a / b);
  }
  else if(ch == '#') { // unary increment
  int a = pop();
  push(a + 1);
  }
  else if(ch == '$') { // unary decrement
  int a = pop();
  push(a - 1);
  }
  }
  return pop();
 }

 int main() {
  char expr[100];

  // Example inputs
  char* inputs[] = {"168*+", "5#", "6/0"};
  int n = 3;

  for(int i=0; i<n; i++) {
  printf("%d\n", evaluate(inputs[i]));
  }

  return 0;
 }

