  if(top < MAX-1)
  stack[++top] = x;
  else
  printf("Stack overflow\n");
 }

 // Pop from stack
 int pop() {
  if(top >= 0)
  return stack[top--];
  else {
  printf("Stack underflow\n");
  return 0;
  }
 }

 // Evaluate a postfix expression
 int evaluate(char* expr) {
  top = -1; // reset stack
  int len = strlen(expr);

  for(int i=0; i<len; i++) {
  char ch = expr[i];

  if(ch == ' ' || ch == '\n') continue; // ignore spaces/newline

  if(isdigit(ch)) {
  push(ch - '0'); // push digit
  }
  else if(ch == '+') {
  int b = pop();
  int a = pop();
  push(a + b);
  }
  else if(ch == '-') {
  int b = pop();
  int a = pop();
  push(a - b);
  }
  else if(ch == '*') {
  int b = pop();
  int a = pop();
  push(a * b);
  }
  else if(ch == '/') {
  int b = pop();
  int a = pop();
  if(b == 0) b += 2; // special rule
  push(a / b);
  }
  else if(ch == '#') { // unary increment
  int a = pop();
  push(a + 1);
  }
  else if(ch == '$') { // unary decrement
  int a = pop();
  push(a - 1);
  }
  }
  return pop();
 }

 int main() {
  char expr[100];
  while(1) {
  if(fgets(expr, sizeof(expr), stdin) == NULL) break;
  if(expr[0] == '\n') break; // empty line to stop
  int result = evaluate(expr);
  printf("%d\n", result);
  }

  return 0;
 }

