#include <stdio.h>
 #include <stdlib.h>
 #include <string.h>
 #include <stdbool.h>

 struct StackNode {
  char data;
  struct StackNode* next;
 };
 struct StackNode* top = NULL;

 struct QueueNode {
  char data;
  struct QueueNode* next;
 };
 struct QueueNode* front = NULL;
 struct QueueNode* rear = NULL;

 void push(char c) {
  struct StackNode* newNode = (struct StackNode*)malloc(sizeof(struct StackNode));
  newNode->data = c;
  newNode->next = top;
  top = newNode;
 }

 char pop() {
  if (top == NULL) return '\0';
  char c = top->data;
  struct StackNode* temp = top;
  top = top->next;
  free(temp);
  return c;
 }

 void enqueue(char c) {
  struct QueueNode* newNode = (struct QueueNode*)malloc(sizeof(struct QueueNode));
  newNode->data = c;
  newNode->next = NULL;
  if (rear == NULL) {
  front = rear = newNode;
  } else {
  rear->next = newNode;
  rear = newNode;
  }
 }

 char dequeue() {
  if (front == NULL) return '\0';
  char c = front->data;
  struct QueueNode* temp = front;
  front = front->next;
  if (front == NULL) rear = NULL;
  free(temp);
  return c;
 }

 void clearData() {
  while (top) pop();
  while (front) dequeue();
 }

 bool isPalindrome(char* str) {
  int len = strlen(str);
  clearData();

  for (int i = 0; i < len; i++) {
  push(str[i]);
  enqueue(str[i]);
  }

  for (int i = 0; i < len; i++) {
  if (pop() != dequeue())
  return false;
  }
  return true;
 }

 int main() {
  int t;
  scanf("%d", &t);

  while (t--) {
  char str[1005];
  scanf("%s", str);

  if (isPalindrome(str))
  printf("YES\n");
  else
  printf("NO\n"); // fixed here
  }
  return 0;
 }

