#include <stdio.h>
 #include <stdlib.h>

 int compare(const void *a, const void *b) {
  return (*(int *)a - *(int *)b);
 }

 int main() {
  int n, t;
  scanf("%d %d", &n, &t);
  int total = n + 2 * t;
  int arr[total]; 

  for (int i = 0; i < n; i++) {
  scanf("%d", &arr[i]);
  }

  int current_size = n;

  // Sort the initial array
  qsort(arr, current_size, sizeof(int), compare);

  // Print initial median
  printf("%d\n", arr[current_size / 2]);

  while (t--) {
  int x, y;
  scanf("%d %d", &x, &y);

  arr[current_size++] = x;
  arr[current_size++] = y;

  // Sort the updated array
  qsort(arr, current_size, sizeof(int), compare);

  // Print new median
  printf("%d\n", arr[current_size / 2]);
  }

  return 0;
 }

