#include <stdio.h>
 #include <stdlib.h>

 typedef struct Node {
  int value;
  struct Node* next;
 } Node;

 // Insert at front
 Node* insertFront(Node* head, int v) {
  Node* newNode = (Node*)malloc(sizeof(Node));
  newNode->value = v;
  newNode->next = head;
  return newNode;
 }

 // Insert at back
 Node* insertBack(Node* head, int v) {
  Node* newNode = (Node*)malloc(sizeof(Node));
  newNode->value = v;
  newNode->next = NULL;
  if (head == NULL) {
  return newNode;
  }

  Node* temp = head;
  while (temp->next != NULL) {
  temp = temp->next;
  }
  temp->next = newNode;
  return head;
 }

 int main() {
  int n;
  scanf("%d", &n);

  Node* head = NULL;
  for (int i = 0; i < n; i++) {
  int p, v;
  scanf("%d %d", &p, &v);

  if (p == 0) {
  head = insertFront(head, v);
  } else {
  head = insertBack(head, v);
  }
  }

  // Print linked list
  Node* current = head;
  while (current != NULL) {
  printf("%d\n", current->value);
  current = current->next;
  }

  return 0;
 }

