#include <stdio.h>
 #include <stdlib.h>

 /* BST Node */
 struct Node {
  int data;
  struct Node *left, *right;
 };

 /* Stack Node */
 struct Stack {
  struct Node* node;
  struct Stack* next;
 };

 /* Stack operations */
 void push(struct Stack** top, struct Node* node) {
  struct Stack* temp = (struct Stack*)malloc(sizeof(struct Stack));
  temp->node = node;
  temp->next = *top;
  *top = temp;
 }

 struct Node* pop(struct Stack** top) {
  struct Stack* temp = *top;
  struct Node* node = temp->node;
  *top = temp->next;
  free(temp);
  return node;
 }

 int isEmpty(struct Stack* top) {
  return top == NULL;
 }

 /* BST Insert */
 struct Node* insert(struct Node* root, int val) {
  if (root == NULL) {
  struct Node* node = (struct Node*)malloc(sizeof(struct Node));
  node->data = val;
  node->left = node->right = NULL;
  return node;
  }
  if (val < root->data)
  root->left = insert(root->left, val);
  else
  root->right = insert(root->right, val);
  return root;
 }

 /* Merge two BSTs */

 void mergeBSTs(struct Node* root1, struct Node* root2) {
  struct Stack *s1 = NULL, *s2 = NULL;

  while (root1 || root2 || !isEmpty(s1) || !isEmpty(s2)) {

  while (root1) {
  push(&s1, root1);
  root1 = root1->left;
  }

  while (root2) {
  push(&s2, root2);
  root2 = root2->left;
  }

  if (isEmpty(s2) || (!isEmpty(s1) && s1->node->data <= s2->node->data)) {
  root1 = pop(&s1);
  printf("%d", root1->data);
  root1 = root1->right;
  } else {
  root2 = pop(&s2);
  printf("%d", root2->data);
  root2 = root2->right;
  }
  }
 }
 int main() {
  int n1, n2, x;
  struct Node *root1 = NULL, *root2 = NULL;

  scanf("%d", &n1);
  for (int i = 0; i < n1; i++) {
  scanf("%d", &x);
  root1 = insert(root1, x);
  }

  scanf("%d", &n2);
  for (int i = 0; i < n2; i++) {
  scanf("%d", &x);
  root2 = insert(root2, x);
  }

  mergeBSTs(root1, root2);
  printf("\b\n");
  return 0;
 }

