#include <stdio.h>
 #include <stdlib.h>

 typedef struct Node {
  int data;
  struct Node* left;
  struct Node* right;
 } Node;


 Node* newNode(int val) {
  Node* node = (Node*)malloc(sizeof(Node));
  node->data = val;
  node->left = node->right = NULL;
  return node;
 }


 Node* insert(Node* root, int val) {
  if (!root) return newNode(val);
  if (val < root->data)
  root->left = insert(root->left, val);
  else
  root->right = insert(root->right, val);
  return root;
 }


 Node* morrisNext(Node** curr) {
  Node* res = NULL;
  while (*curr) {
  if (!(*curr)->left) {
  res = *curr;
  *curr = (*curr)->right;
  break;
  } else {
  Node* pre = (*curr)->left;
  while (pre->right && pre->right != *curr)
  pre = pre->right;
  if (!pre->right) {
  pre->right = *curr;
  *curr = (*curr)->left;
  } else {
  pre->right = NULL;
  res = *curr;
  *curr = (*curr)->right;
  break;
  }
  }
  }
  return res;
 }

 void mergeBSTs(Node* root1, Node* root2) {
  Node* curr1 = root1;
  Node* curr2 = root2;
  Node* n1 = morrisNext(&curr1);
  Node* n2 = morrisNext(&curr2);

  while (n1 || n2) {
  if (!n1) {
  printf("%d ", n2->data);
  n2 = morrisNext(&curr2);
  } else if (!n2) {
  printf("%d ", n1->data);
  n1 = morrisNext(&curr1);
  } else {
  if (n1->data < n2->data) {
  printf("%d ", n1->data);
  n1 = morrisNext(&curr1);
  } else {
  printf("%d ", n2->data);
  n2 = morrisNext(&curr2);
  }
  }
  }
  printf("\n");
 }

 int main() {
  int n1, n2, val;
  Node* root1 = NULL;
  Node* root2 = NULL;

  scanf("%d", &n1);
  for (int i = 0; i < n1; i++) {
  scanf("%d", &val);
  root1 = insert(root1, val);
  }

  scanf("%d", &n2);
  for (int i = 0; i < n2; i++) {
  scanf("%d", &val);
  root2 = insert(root2, val);
  }

  mergeBSTs(root1, root2);

  return 0;
 }

