  root->right = insert(root->right, val);
  return root;
 }


 Node* morrisNext(Node** curr) {
  Node* res = NULL;
  while (*curr) {
  if (!(*curr)->left) {
  res = *curr;
  *curr = (*curr)->right;
  break;
  } else {
  Node* pre = (*curr)->left;
  while (pre->right && pre->right != *curr)
  pre = pre->right;
  if (!pre->right) {
  pre->right = *curr;
  *curr = (*curr)->left;
  } else {
  pre->right = NULL;
  res = *curr;
  *curr = (*curr)->right;
  break;
  }
  }
  }
  return res;
 }


 void mergeBSTs(Node* root1, Node* root2) {
  Node* curr1 = root1;
  Node* curr2 = root2;
  Node* n1 = morrisNext(&curr1);
  Node* n2 = morrisNext(&curr2);

  int first = 1; 
  while (n1 || n2) {
  int val;
  if (!n1) val = n2->data;
  else if (!n2) val = n1->data;
  else val = (n1->data < n2->data) ? n1->data : n2->data;

